#!/usr/bin/env node
// CI guard: fails if src/lib/seo/marketing-dates.ts (generated by
// scripts/seo/generate-marketing-dates.mjs from each page's own git history)
// has drifted from what the generator produces right now.
//
// Why this exists: the generator script has existed since PR #3350 (2026-09-02)
// specifically to stop sitemap <lastmod> going stale on marketing pages, but
// nothing ever re-ran it — it is a manual "regenerate and commit" step with no
// CI enforcement. Confirmed live 2026-09-05: 6 of 10 marketing pages had
// drifted again since #3350 (e.g. /pricing committed 2026-08-20 vs its real
// last change 2026-09-04, 15 days stale) — the exact recurrence the generator
// was built to prevent, just with nothing catching it a second time. Same
// class of bug, same fix shape as the tailwind/client-server-boundary guards
// already wired into ci.yml: regenerate in-memory and diff against the
// committed file rather than trust a human to remember.

import { execSync } from "node:child_process";
import { readFileSync } from "node:fs";

const generated = execSync("node scripts/seo/generate-marketing-dates.mjs", { encoding: "utf8" });
const committed = readFileSync("src/lib/seo/marketing-dates.ts", { encoding: "utf8" });

if (generated !== committed) {
  console.error(
    "FAIL: src/lib/seo/marketing-dates.ts is stale — it no longer matches what " +
      "scripts/seo/generate-marketing-dates.mjs produces from current git history.\n" +
      "Regenerate and commit:\n" +
      "  node scripts/seo/generate-marketing-dates.mjs > src/lib/seo/marketing-dates.ts",
  );
  process.exit(1);
}

console.log("OK: marketing-dates.ts matches the generator output.");
